// Workflow-level unhandled error — sign a callback so server logs it
const crypto = require('crypto');
const SECRET = 'c56cb3e88c57ea77929fdbec379fb6ff1ab72fef61cee9084e9cb263892d8887';
const err = $input.first().json;

const body = JSON.stringify({
  event_type: 'anomaly_routed',
  flow_id: 'N8N-S03',
  brand_id: null,
  payload: {
    anomaly_id:   'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,c=>{const r=Math.random()*16|0;return(c==='x'?r:(r&0x3|0x8)).toString(16);}),
    anomaly_type: 'n8n_failure',
    severity:     'critical',
    source_flow:  'N8N-S03',
    message:      `Unhandled error in "${err.node?.name || 'unknown'}": ${err.message || 'unknown'}`,
    target_copilot: 'tech',
    human_gate: false,
    is_blocked: false,
    ceo_error: true
  }
});
const sig = crypto.createHmac('sha256', SECRET).update(body).digest('hex');
return {
  _body: body,
  _headers: {
    'content-type': 'application/json',
    'x-n8n-signature': sig,
    'x-n8n-request-id': `${$execution.id}-wferr-s03`,
    'x-n8n-timestamp': new Date().toISOString()
  }
};

// Webhook v2 wraps POST body under .body
const raw = $input.first().json;
const p = raw.body ?? raw;
// Ensure anomaly_id is always a valid UUID — the anomaly_records PK is uuid type.
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const makeUUID = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
  const r = Math.random() * 16 | 0;
  return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
});
const rawId = p.anomaly_id || '';
return {
  anomaly_id:   UUID_RE.test(rawId) ? rawId : makeUUID(),
  anomaly_type: p.anomaly_type || p.error_type || 'UNKNOWN',
  severity:     (p.severity    || 'warning').toLowerCase(),
  source_flow:  p.source_flow  || p.flow_id || p.source || 'unknown',
  brand_id:     p.brand_id     || null,
  message:      p.message      || p.error_message || 'No message',
  details:      p.details      || p.event_data    || {},
  timestamp:    p.timestamp    || new Date().toISOString()
};

