// CEO succeeded — build enriched anomaly_routed callback
const crypto = require('crypto');
const SECRET = 'c56cb3e88c57ea77929fdbec379fb6ff1ab72fef61cee9084e9cb263892d8887';
const ceoResult = $input.first().json;
const anomaly = $('Parse Anomaly').first().json;

const ceoData = Array.isArray(ceoResult) ? ceoResult[0] : ceoResult;
const decision = ceoData?.result?.decision || ceoData?.decision || {};

const humanGate = decision.human_gate_required === true;
const isBlocked = decision.confidence_mode === 'Blocked';

const routingMap = {
  tech:       ['ceo_call_failed','coo_call_failed','n8n_failure','supabase_error',
               'api_error','extraction_failed','revision_failed','correction_failed',
               'pipeline_degraded','weavy_timeout','ai_provider_error','timeout'],
  management: ['cost_ceiling_alert','cost_ceiling_approaching','cost_ceiling_breached',
               'upgrade_readiness_report','growth_opportunity',
               'maintenance_report','cost_spike'],
  production: ['quality_regression','dialect_not_confirmed','hard_block',
               'correction_rejected','held_post','content_quality_low']
};
let targetCopilot = decision.target_copilot || null;
if (!targetCopilot || targetCopilot === 'auto') {
  const at = (anomaly.anomaly_type || '').toLowerCase();
  for (const [c, types] of Object.entries(routingMap)) {
    if (types.some(t => at.includes(t) || t.includes(at))) { targetCopilot = c; break; }
  }
  targetCopilot = targetCopilot || 'tech';
}

const body = JSON.stringify({
  event_type: 'anomaly_routed',
  flow_id: 'N8N-S03',
  brand_id: anomaly.brand_id || null,
  payload: {
    anomaly_id:         anomaly.anomaly_id,
    anomaly_type:       anomaly.anomaly_type,
    severity:           anomaly.severity,
    source_flow:        anomaly.source_flow,
    message:            anomaly.message,
    details:            anomaly.details,
    target_copilot:     targetCopilot,
    human_gate:         humanGate,
    is_blocked:         isBlocked,
    reasoning:          decision.reasoning || '',
    human_gate_reasons: decision.human_gate_reasons || [],
    confidence_mode:    decision.confidence_mode || 'Standard',
    timestamp:          anomaly.timestamp
  }
});
const sig = crypto.createHmac('sha256', SECRET).update(body).digest('hex');
return {
  anomaly, decision,
  target_copilot: targetCopilot,
  human_gate: humanGate,
  is_blocked: isBlocked,
  confidence_mode: decision.confidence_mode || 'Standard',
  needs_qa: (humanGate || isBlocked) && !!anomaly.brand_id,
  _body: body,
  _headers: {
    'content-type': 'application/json',
    'x-n8n-signature': sig,
    'x-n8n-request-id': `${$execution.id}-routed-s03`,
    'x-n8n-timestamp': new Date().toISOString()
  }
};

